"""Differential tests for Wolfram batch W11 (strings & text: templates, text search/indexing, diffs, sequence
alignment, bio-sequences, hashing).

Expected values are Wolfram Language results from the reference pages (reference.wolfram.com/language/ref/<Name>),
or values checked here against independent references (hashlib, unicodedata, a direct BM25 computation, hand-worked
alignments and diff3 merges). Association key order is unspecified in Wolfram for tied counts, so those cases use
KeySort. Variables are prefixed w11 so cases do not leak into each other.
"""
import pytest

from _harness import Pred, Raises, check, ids

